// Read-only helpers shared by the new tab prototypes. Data comes from
// window.SNAPSHOT (out/snapshot.js, generated by scripts/preview.mjs).
(function () {
  const snap = window.SNAPSHOT;
  if (!snap) {
    document.body.innerHTML =
      "<p style='padding:24px'>No snapshot. Run <code>node scripts/preview.mjs</code> first.</p>";
    throw new Error("window.SNAPSHOT missing");
  }

  // Fixed column order for the core hubs: muscle memory beats optimal order.
  const CORE = ["Jira", "GitHub", "Confluence", "AWS"];
  const HUB_COLOR = {
    Jira: "--hub-jira",
    GitHub: "--hub-github",
    Confluence: "--hub-confluence",
    AWS: "--hub-aws",
    Microsoft: "--hub-microsoft",
    AI: "--hub-ai",
  };

  const hubs = snap.hubs;
  const byName = new Map(hubs.map((h) => [h.name, h]));

  // Primary text of an entry, without the parts the hub already implies.
  function text(e) {
    if (e.key.startsWith("jira:") && e.title?.startsWith(`[${e.label}]`)) {
      return e.title.slice(e.label.length + 2).trim();
    }
    if (e.key.startsWith("github:") && e.label?.includes("/")) return e.label.split("/")[1];
    return e.title || e.label || e.key;
  }

  // Secondary text: issue key, repo owner, PR tag, local port.
  function tag(e) {
    if (e.key.startsWith("jira:") && /^[A-Z]+-\d+$/.test(e.label ?? "")) return e.label;
    if (e.key.startsWith("github:") && e.label?.includes("/")) return e.label.split("/")[0];
    if (e.key.startsWith("github:") && e.label?.includes("#")) return e.label;
    if (e.label?.startsWith(":")) return e.label;
    return "";
  }

  const rising = (e) => e.trend === "up" || e.trend === "new";
  const color = (hub) => `var(${HUB_COLOR[hub] ?? "--hub-other"})`;
  const ago = (t) => {
    const d = Math.round((snap.asOf - t) / 86400e3);
    return d === 0 ? "today" : `${d}d`;
  };

  function all() {
    return hubs.flatMap((h) => h.entries.map((e) => ({ ...e, hub: h.name })));
  }

  // Case-insensitive match on every word, ranked by score.
  function search(q, limit = 12) {
    const words = q.toLowerCase().split(/\s+/).filter(Boolean);
    if (!words.length) return [];
    return all()
      .filter((e) => {
        const hay = `${e.hub} ${e.label ?? ""} ${e.title ?? ""} ${e.href}`.toLowerCase();
        return words.every((w) => hay.includes(w));
      })
      .sort((a, b) => b.score - a.score)
      .slice(0, limit);
  }

  function esc(s) {
    return String(s).replace(/[&<>"]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" })[c]);
  }

  // Wire a search box: "/" focuses it, Enter opens the first hit, Esc clears.
  function bindSearch(input, onResults) {
    const run = () => onResults(search(input.value), input.value.trim());
    input.addEventListener("input", run);
    input.addEventListener("keydown", (ev) => {
      if (ev.key === "Enter") {
        const first = search(input.value, 1)[0];
        if (first) window.open(first.href, "_blank");
      }
      if (ev.key === "Escape") {
        input.value = "";
        run();
      }
    });
    document.addEventListener("keydown", (ev) => {
      if (ev.key === "/" && document.activeElement !== input) {
        ev.preventDefault();
        input.focus();
      }
    });
  }

  window.Proto = { snap, hubs, byName, CORE, text, tag, rising, color, ago, all, search, esc, bindSearch };
})();
